import { VisualBanco } from './bancos';

/**
 * #265: selo de cada serviço que costuma cobrar todo mês (assinaturas, telefone, apps), no mesmo padrão dos bancos
 * (ADR 0024). Tudo vai no build: nada é baixado da internet (CSP).
 *
 * - Com `caminho`: o desenho da marca do Simple Icons (https://simpleicons.org, licença CC0 1.0), viewBox 24×24, com a
 *   cor da marca de fundo. As marcas continuam sendo dos seus donos; aqui servem só para identificar a cobrança na tela
 *   do próprio usuário.
 * - Com `sigla`: selo próprio, com a cor da marca e uma sigla curta (o Simple Icons não tem a marca). Não é o logotipo
 *   oficial.
 *
 * O serviço é reconhecido pelo texto da cobrança (`termos`, sem acento e em maiúsculas), na ordem desta lista: o mais
 * específico vem antes ("Google YouTubePremium" é YouTube, não Google). Termo de uma palavra casa com o começo de uma
 * palavra do texto ("YOUTUBE" casa com "YOUTUBEPREMIUM"); com até 4 letras, só com a palavra inteira ("TIM" não casa
 * com "TIMBRE", nem "UBER" com "UBERLANDIA"). Termo de várias palavras casa com elas em sequência.
 * Gerado a partir do pacote simple-icons 16.35.0; serviço novo: acrescente aqui (e o caminho do Simple Icons, se tiver).
 * As cores dos selos com sigla são aproximadas das marcas; não são o logotipo oficial. O Petlove tem um desenho próprio
 * (uma pata), também não oficial.
 */
export interface Servico { chave: string; termos: string[]; visual: VisualBanco }

