/** As palavras do texto, sem acento, em maiúsculas (separadas por qualquer coisa que não seja letra ou número). */
export function palavras(texto: string | null | undefined): string[] {
  return (texto ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().split(/[^A-Z0-9]+/).filter(Boolean);
}

function casa(termo: string, texto: string[]): boolean {
  const partes = termo.split(' ');
  if (partes.length > 1) {
    const junto = ` ${texto.join(' ')} `;
    return junto.includes(` ${termo} `) || texto.join('').includes(partes.join(''));
  }
  return texto.some((p) => (termo.length <= 4 ? p === termo : p.startsWith(termo)));
}

/** O serviço da cobrança pelos textos dela (o texto da cobrança e o nome), na ordem; null se nenhum. */
export function servicoDe(...textos: (string | null | undefined)[]): Servico | null {
  for (const t of textos) {
    const p = palavras(t);
    if (!p.length) continue;
    const achado = SERVICOS.find((s) => s.termos.some((termo) => casa(termo, p)));
    if (achado) return achado;
  }
  return null;
}
